// Agente PERRO 🐕 — hecho ENTERO desde el panel de Agentes, sin escribir un JSON a mano.
//
// Reparto de responsabilidades (§0: app.js NO se toca para hacer un agente):
// · app.js (framework) ....... nada suyo. No sabe qué es un perro; solo que hay piezas `efimera`
//                             que no entran en mundo.json.
// · mundo-autoarranque ....... `game.esqueletos` estampa las piezas, compone la matriz de cada una
//                             y persigue con la MISMA pasoSeguir que usa `seguir`.
// · data/agentes/perro.json .. el DOCUMENTO: qué piezas, dónde van, cómo articulan. **Se edita en
//                             el panel** (pestaña Agentes), no aquí.
// · este snippet ............. dónde y cuándo se planta. Nada más.
//
// Qué hace: te sigue A UNA DISTANCIA. `seguir.distancia` no es un mínimo, es un SITIO donde estar:
// se para a 3 bloques de ti y, si te acercas más, retrocede. Cuatro patas en diagonal (delantera
// izquierda con trasera derecha), la cabeza te sigue con la mirada y la cola menea sobre el eje y.
//
// ⚠️ Es EFÍMERO a propósito: no entra en mundo.json y desaparece al recargar la pestaña.
// ⚠️ Las patas NO tienen colisión (el rig las gira y los envoltorios de colisión solo trasladan):
//    el perro choca por su torso. Tampoco te hace daño ni te empuja: te sigue, nada más.

if (typeof mc === 'undefined' || !mc.grid || !mc.pos) {
  console.warn('agente-perro: esto solo va en la pestaña del Mundo (modo Mundo abierto).');
  return;
}
if (typeof game === 'undefined' || !game.esqueletos || !game.esqueletos.crear) {
  console.warn('agente-perro: falta el motor de esqueletos. Ejecuta antes el snippet '
    + '«mundo-autoarranque» (v1.19 o más).');
  return;
}

// El id en data/agentes/ — y, a la vez, el `nombre` del documento, que es por lo que se reconocen
// aquí abajo los perros que ya estaban vivos. Si le cambias el nombre al agente, cámbialo aquí.
const AGENTE = 'perro';

// ── Plantarlo ─────────────────────────────────────────────────────────────────────────────────
// Reejecutar el snippet no debe dejar una jauría suelta por el mapa: se retiran los suyos (por
// nombre) y NO los demás agentes, que pueden ser de otro snippet.
const previos = (game.esqueletos._vivos || []).slice()
  .filter(r => r && !r.quitado && r.nombre === AGENTE);
previos.forEach(r => game.esqueletos.quitar(r));
if (previos.length) console.log('agente-perro: retirado(s) ' + previos.length + ' perro(s) anterior(es).');

// A tu lado, no delante: un perro que te sigue empieza cerca. 3 bloques es justo su `distancia`,
// así que nace ya en su sitio y no da el tirón inicial (misma cuenta que usa app.js para el frente
// de la cámara).
const p = mc.pos, fx = -Math.sin(mc.yaw), fz = -Math.cos(mc.yaw);
let x = Math.round(p[0] + fx * 3), z = Math.round(p[2] + fz * 3);
// ⚠️ mcSurfaceY solo ve la rejilla (terreno y assets macizos de 16³): si ahí hay una escalera o
// cualquier estructura fina, el perro aparece a su altura y no encima. Cae por su peso al andar.
let sy = mcSurfaceY(x, z);
if (sy < 0) {                      // fuera del mapa o columna vacía: al pie del jugador
  x = Math.round(p[0]); z = Math.round(p[2]);
  sy = mcSurfaceY(x, z);
}
if (sy < 0) { console.warn('agente-perro: no encuentro suelo donde plantarlo.'); return; }

const perro = await game.esqueletos.crear(AGENTE, x, sy + 1, z);
if (!perro) return;                // crear() ya ha dicho por consola qué le faltaba

console.log('🐕 perro #' + perro.id + ' en ' + x + ',' + (sy + 1) + ',' + z
  + ' — te sigue a 3 bloques; si te acercas más, retrocede.');
console.log('   game.esqueletos.lista()   ·   game.esqueletos.quitar(' + perro.id + ')');
